mapper.select:
SELECT A.HANDLE_SEQNO handleSeqno, A.HANDLE_FILE_NAME handleFileName, A.HANDLE_FILE_PATH handleFilePath, A.HANDLE_FILE_TYPE handleFileType, A.FILE_READ_START_TIME fileReadStartTime, A.FILE_READ_END_TIME fileReadEndTime, A.FILE_DATA_COUNT fileDataCount, A.FILE_HANDLE_STATUS fileHandleStatus, A.FILE_HANDLE_RESULT_MSG fileHandleResultMsg, A.ERROR_FILE_SEQNO errorFileSeqNo FROM CHB_FILE_READ_MONITOR_INFO A
#{handleFileType,jdbcType=VARCHAR}
#{fileHandleStatus,jdbcType=VARCHAR}
AND DATE_FORMAT(A.FILE_READ_START_TIME,'%Y-%m-%d') >= #{startDate}
AND DATE_FORMAT(A.FILE_READ_END_TIME,'%Y-%m-%d') <=#{endDate}
order by A.update_time desc
